def affected(startnum, endnum):
    # Original keeps n iff every digit is nonzero and divides n.
    # Mutant keeps n iff every digit is nonzero and n % d == 1.
    # The two kept-sets are disjoint (a digit d cannot both divide n and leave remainder 1),
    # so the outputs differ exactly when some n in the range is kept by either version.
    def p(n):
        ds = [int(c) for c in str(n)]
        return all(d != 0 and n % d == 0 for d in ds)
    def q(n):
        ds = [int(c) for c in str(n)]
        return all(d != 0 and n % d == 1 for d in ds)
    return any(p(n) or q(n) for n in range(startnum, endnum + 1))
